def calcular_media(numeros):
    soma = sum(numeros)
    return soma / len(numeros)

def remover_duplicatas(lista):
    seen = set()
    i = 0
    while i < len(lista):
        if lista[i] in seen:
            lista.pop(i)  # bug: modifica a lista original do chamador
        else:
            seen.add(lista[i])
            i += 1
    return lista

def somar_lista(numeros):
    if not numeros:
        return 0
    return sum(numeros)

def fatorial(n):
    if n < 0:
        raise ValueError('Negativo')
    resultado = 1
    for i in range(1, n + 1):
        resultado *= i
    return resultado
